import{_ as t,c as s,o as n,j as e,a as r}from"./chunks/framework.BKeRpnBD.js";const m=JSON.parse('{"title":"《横渠易说》简介","description":"横渠易说 - 《横渠易说》简介","frontmatter":{"title":"《横渠易说》简介","description":"横渠易说 - 《横渠易说》简介"},"headers":[],"relativePath":"zh/classics/hengqu/001.md","filePath":"zh/classics/hengqu/001.md"}'),l={name:"zh/classics/hengqu/001.md"};function c(o,a,i,d,p,h){return n(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"《横渠易说》简介",tabindex:"-1"},[r("《横渠易说》简介 "),e("a",{class:"header-anchor",href:"#《横渠易说》简介","aria-label":"Permalink to “《横渠易说》简介”"},"​")],-1),e("p",null,"探索易学深邃，领略智慧之光。在这里，我们不仅提供《横渠易说》等经典著作的在线阅读，更汇聚了周易八卦、易经六十四卦等丰富内容，满足您对易学知识的全面需求。从周易全文的完整呈现，到易经讲解的深入浅出，再到周易预测的神秘魅力，我们致力于为您打造一个全方位、多层次的易学学习平台。无论您是初学者还是资深爱好者，都能在这里找到属于自己的智慧启迪和心灵归宿。张载的学术思想以《易经》为宗，以《中庸》为体，以孔孟为法，其学说强调了天人合一的哲学理念，并对后世的理学发展产生了深远影响。",-1),e("p",null,"《横渠易说》的主要内容形成于张载三十岁至五十岁之间，并在晚年有所增益和修订。张载在书中不仅继承了传统的象数易学，更侧重于义理的阐发，并根据自己的理论要求进行了创新。他提出了刚柔说、取象说、爻位说等易学理论，并对《周易》进行了深入的哲学诠释。",-1),e("p",null,"《横渠易说》的学术史意义重大，它不仅代表了张载思想的逐渐形成与成熟，而且对宋明理学以及后来的中国文化产生了深远的影响。此书的校注版本由刘泉校注，对书中的疑难字词、概念范畴等进行了注释和分析，并附有张载的传记、书目序跋、历代评议等文献作为附录。",-1),e("p",null,"张载的《横渠易说》也被认为是气学《易》学的代表作，其哲学思想以“气”为万物之本，认为“天惟运动一气，鼓万物而生”。这本书体现了张载早年的学术观点，尽管文字相对粗糙，但已经具备了唯物主义的基本观点。",-1)])])}const _=t(l,[["render",c]]);export{m as __pageData,_ as default};
